"""Build a vector comparison page from a retained evaluated fitting run."""
import argparse,html,json
from pathlib import Path

p=argparse.ArgumentParser();p.add_argument('folder',type=Path);a=p.parse_args()
data=json.loads((a.folder/'evaluations.json').read_text());cards=[]
for row in sorted(data['rows'],key=lambda r:({'user':0,'curves':1,'alpha':2}.get(r['name'],3),r['count'],r['seed'])):
    if row['strength']==0:continue
    base=next(r for r in data['rows'] if r['name']==row['name'] and r['family']==row['family'] and r['count']==row['count'] and r['seed']==row['seed'] and r['strength']==0)
    b,m=base['measurements'],row['measurements'];title=f"{row['name']} · {row['family']} · {row['count']} shapes · seed {row['seed']} · smoothing {row['strength']}"
    source=f"{row['name']}/source.svg" if (a.folder/row['name']/'source.svg').exists() else f"{row['name']}/source.png"
    cards.append(f'''<article><h2>{html.escape(title)}</h2><div class="row"><figure><img src="{source}"><figcaption>Source</figcaption></figure><figure><div class="compare"><img src="{row['folder']}/controls.svg"><div class="over"><img src="{base['folder']}/controls.svg"></div></div><input type="range" min="0" max="100" value="50" aria-label="Reveal baseline versus smoothing"><figcaption>Left: original objective · Right: contour objective</figcaption></figure></div><p>Tangent error: {b['matched_edge_tangent_error']:.5f} → {m['matched_edge_tangent_error']:.5f}; unmatched edges: {b['unmatched_output_edge_fraction']:.2%} → {m['unmatched_output_edge_fraction']:.2%}; missing source edges: {b['missing_source_edge_fraction']:.2%} → {m['missing_source_edge_fraction']:.2%}.</p><details><summary>Pixel and construction diagnostics</summary><p>RGBA MSE {b['premult_mse']:.6f} → {m['premult_mse']:.6f}. Alpha spill {b['alpha_spill']:.2f} → {m['alpha_spill']:.2f}; deficit {b['alpha_deficit']:.2f} → {m['alpha_deficit']:.2f}. Zero-alpha controls {base['zero_alpha']} → {row['zero_alpha']}. Runtime {base['seconds']:.2f}s → {row['seconds']:.2f}s.</p><p>Families {html.escape(str(base['shape_counts']))} → {html.escape(str(row['shape_counts']))}</p></details><p><a href="{base['folder']}/controls.svg">Original vector</a> · <a href="{row['folder']}/controls.svg">Smoothed vector</a> · <a href="{row['folder']}/vector-1024.png">1024px geometry render</a></p></article>''')
(a.folder/'comparison.html').write_text('''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Contour fitting comparisons</title><style>body{font:16px system-ui;max-width:1120px;margin:auto;padding:24px;background:#18202a;color:#eee}a{color:#bde0ff}article{border-top:1px solid #667;padding-top:20px;margin-top:32px}.row{display:flex;gap:24px}figure{flex:1;min-width:0;margin:0}img{display:block;width:100%;background:repeating-conic-gradient(#888 0% 25%,#aaa 0% 50%) 0/20px 20px}.compare{position:relative}.over{position:absolute;inset:0;clip-path:inset(0 50% 0 0)}input{width:100%}h2{font-size:20px}@media(max-width:650px){.row{flex-direction:column}}</style><h1>Contour fitting comparisons</h1><p>Equal requested counts, seeds and detail; all generated outputs retained. Slider images are exported game-control vectors, not enlarged fitting pixels. Source images are independent fixture SVGs or the supplied raster. Measurements at256px are separate diagnostics, not a calibrated human quality/identity score. Both improvements and regressions remain visible. No new primitive, source-alpha clipping or reduced fitting effort.</p><p><a href="results.json">Reproducible settings</a> · <a href="evaluations.json">Measurements</a></p>'''+''.join(cards)+'''<script>document.querySelectorAll('input').forEach(i=>i.oninput=()=>i.closest('figure').querySelector('.over').style.clipPath='inset(0 '+(100-i.value)+'% 0 0)');</script>''',encoding='utf-8')
print('Wrote',len(cards),'paired vector comparisons')
